package com.bank.fraud;

import java.util.Arrays;
import java.util.logging.*;

public class SortColorsDemo {
    private static final Logger log = Logger.getLogger(SortColorsDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        RiskQueueSorter sorter = new RiskQueueSorter();

        // Risk tiers: 0 low, 1 medium, 2 high
        int[] tiers = {2, 0, 1, 2, 1, 0, 0, 2, 1};
        log.info(() -> "Before: " + Arrays.toString(tiers));

        sorter.sortByTier(tiers);
        log.info(() -> "After : " + Arrays.toString(tiers));
    }
}

