class RiskQueueSorter {
    private static final Logger log = Logger.getLogger(RiskQueueSorter.class.getName());

    // Dutch National Flag: one pass, three pointers. O(n) time, O(1) space.
    void sortByTier(int[] a) {
        int low = 0, mid = 0, high = a.length - 1;
        while (mid <= high) {
            if (a[mid] == 0) {
                swap(a, low++, mid++);   // 0 → front region
            } else if (a[mid] == 1) {
                mid++;                   // 1 stays in middle
            } else {
                swap(a, mid, high--);    // 2 → back region; do NOT move mid
            }
        }
        log.fine(() -> "Partitioned low/mid/high in one pass");
    }

    private void swap(int[] a, int i, int j) {
        int t = a[i]; a[i] = a[j]; a[j] = t;
    }
}

